codeExamples.code:
-- Exclude active customers
SELECT * FROM customers
WHERE NOT (status = 'active');

-- Exclude a numeric range (inclusive bounds)
SELECT * FROM products
WHERE price NOT BETWEEN 10 AND 20;

-- Exclude names starting with 'A'
SELECT * FROM customers
WHERE name NOT LIKE 'A%';

-- DANGER: if the subquery returns any NULL, this yields NO rows
SELECT c.customer_id
FROM customers c
WHERE c.customer_id NOT IN (
    SELECT o.customer_id FROM orders o   -- customer_id may be NULL here
);

-- NULL-safe equivalent: customers with no orders
SELECT c.customer_id
FROM customers c
WHERE NOT EXISTS (
    SELECT 1 FROM orders o
    WHERE o.customer_id = c.customer_id
);

-- Original positive predicate
SELECT * FROM accounts
WHERE status = 'active' AND region = 'US';

-- Negation done WRONG (NOT binds tighter than AND)
SELECT * FROM accounts
WHERE NOT status = 'active' AND region = 'US';
-- Parses as: (NOT status = 'active') AND region = 'US'

-- Negation done RIGHT via De Morgan: NOT (a AND b) = (NOT a) OR (NOT b)
SELECT * FROM accounts
WHERE status <> 'active' OR region <> 'US';
